fn to_lowercase(str1: &Vec<char>) -> Vec<char> {
    // Iterate over each character in the input vector
    // For each character, check if it is uppercase ASCII 'A'..='Z'
    // If yes, convert it to lowercase by adding the offset between 'a' and 'A'
    // Otherwise, keep the character unchanged
    str1.iter()
        .map(|&c| {
            if c >= 'A' && c <= 'Z' {
                // Convert uppercase to lowercase by using ASCII arithmetic
                // 'a' as u8 - 'A' as u8 == 32
                ((c as u8) + 32) as char
            } else {
                c
            }
        })
        .collect()
}